          // Set the result schema to undefined to allow MCP to rely on the
          // default schema.
          undefined,
          requestOptions,
        );
        functionCallResponseParts.push({
          functionResponse: {
            name: functionCall.name,
            response: callToolResponse.isError
              ? {error: callToolResponse}
